  {"id": "A-6", "name": "decision robustness", "question": "Do the two headline swap verdicts stay positive under every A-5 variant?", "script": "report/after-reports/postmortem-2026-10-19/rt_decisions.py", "record": "report/after-reports/postmortem-2026-10-19/rt_decisions.json", "commit_field": null, "added": "2026-10-19"},
